from collections import Counter
# Step 3 law candidates: objects slide toward the LARGEST object (the anchor). Simulate greedy:
# anchor = largest extended comp; every other comp slides step-by-step along one of 8 dirs toward anchor,
# stopping as soon as it touches (orth or diag?) another comp or border. Ties: smallest |dr| first? Check demos.
def solve(gi,anchor_idx=None):
    bg=Counter(x for r in gi for x in r).most_common(1)[0][0]
    H,W=len(gi),len(gi[0])
    groups=[]; used=set()
    for r in range(H):
        for c in range(W):
            if gi[r][c]==bg or (r,c) in used: continue
            st=[(r,c)]; cells=set(); cl=Counter()
            while st:
                a,b=st.pop()
                if (a,b) in cells: continue
                cells.add((a,b)); cl[gi[a][b]]+=1
                for dr in(-1,0,1):
                    for dc in(-1,0,1):
                        x,y=a+dr,b+dc
                        if 0<=x<H and 0<=y<W and gi[x][y]!=bg and (x,y) not in cells: st.append((x,y))
            for x,y in cells: used.add((x,y))
            col=max(cl,key=lambda v:cl[v])
            groups.append({'cells':frozenset(cells),'col':col})
    # majority recolor
    for i,grp in enumerate(groups):
        cl=Counter()
        for a,b in grp['cells']: cl[gi[a][b]]+=1
        grp['col']=max(cl,key=lambda v:cl[v])
    anch=max(groups,key=lambda g:len(g['cells']))
    rest=groups[:]
    for i,g in enumerate(rest):
        if g is anch: continue
        g.setdefault('pos',(min(a for a,b in g['cells']),min(b for a,b in g['cells'])))
    # placeholder sim later
    return groups,bg,H,W
