def solve(g):
    H,W=len(g),len(g[0]); cnt=collections.Counter(x for r in g for x in r)
    bg=cnt.most_common(1)[0][0]
    # separator lines: full row/col mostly one non-bg color. Detect by: exists a value v!=bg with count>=max(H,W)*0.7 on a line
    seps=[]
    for i in range(H):
        row=g[i]; vals=collections.Counter(row)
        top,n=vals.most_common(1)[0]
